<?php
// Catalog edits/uploads stay inside the guarded audit database and tracked test files.
$catalog=request('admin-avatars')['avatars'];
check(count($catalog)===count(json_decode(file_get_contents(__DIR__.'/../data/avatars.json'),true)),'avatar migration preserves all existing keys, names and motifs');
$astra=array_values(array_filter($catalog,fn($a)=>$a['avatar_key']==='astra'))[0];
check($astra['unlock_rule']==='hero_first_try','seeded reward rule survives catalog migration');
$fields=['context'=>'avatar'];
replace_media($fields,$png,403,false,'admin-image-upload');
replace_media($fields,'not a raster image',422,true,'admin-image-upload');
$chunk=static fn($type,$bytes)=>pack('N',strlen($bytes)).$type.$bytes.pack('N',crc32($type.$bytes));
$rectangle="\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',2,1,8,6,0,0,0)).$chunk('IDAT',gzcompress("\0".str_repeat("\xff",8))).$chunk('IEND','');
replace_media($fields,$rectangle,422,true,'admin-image-upload');
check(true,'avatar upload rejects rectangular raster images');
$uploaded=replace_media($fields,$png,200,true,'admin-image-upload');$mediaTestFiles[]=QUIZ_HERO_PUBLIC_ROOT.'/'.$uploaded['path'];
check(str_starts_with($uploaded['path'],'images/uploads/avatars/'),'avatar upload uses persistent avatar upload directory');
$uploadedAgain=replace_media($fields,$png,200,true,'admin-image-upload');$mediaTestFiles[]=QUIZ_HERO_PUBLIC_ROOT.'/'.$uploadedAgain['path'];
check($uploadedAgain['path']!==$uploaded['path'],'same source filename can be uploaded again without overwriting an existing profile motif');
$create=['label'=>'Audit hero '.$suffix,'image'=>$uploaded['path']];
request('admin-avatar-save',$create,403,'',false);
request('admin-avatar-save',$create+['unlockRule'=>'hero_first_try'],422);
request('admin-avatar-save',['label'=>'','image'=>$uploaded['path']],422);
request('admin-avatar-save',['label'=>'Bad path','image'=>'images/../api/index.php'],422);
$created=request('admin-avatar-save',$create);
$createdRow=array_values(array_filter(request('admin-avatars')['avatars'],fn($a)=>$a['avatar_key']===$created['key']))[0];
check($createdRow['label']===$create['label']&&$createdRow['unlock_rule']===null&&$createdRow['avatar_key']!=='','new named profile image gets a stable generated key and free availability');
check(in_array($created['key'],array_column(request('avatars'),'key'),true),'public avatar catalog exposes admin-created profile image');
$entry=['key'=>$created['key'],'label'=>'Renamed audit hero','image'=>$uploaded['path'],'contentVersion'=>$createdRow['contentVersion']];
request('admin-avatar-save',$entry);request('admin-avatar-save',$entry,409);
check($pdo->query('SELECT label FROM quiz_avatars WHERE avatar_key='.$pdo->quote($created['key']))->fetchColumn()==='Renamed audit hero','rename preserves stable identity and stale edits are rejected');
$owner=(int)$pdo->query('SELECT id FROM quiz_users WHERE username='.$pdo->quote($other))->fetchColumn();
$pdo->prepare('INSERT INTO quiz_user_avatar_unlocks(user_id,avatar_key,rule_key,is_backfill) VALUES(?,?,?,1)')->execute([$owner,'astra','hero_first_try']);
request('account-login',['identifier'=>$other,'password'=>$password]);request('account-update',['username'=>$other,'avatarKey'=>'astra']);
$editAstra=['key'=>'astra','label'=>'Audit Astra','image'=>$uploaded['path'],'contentVersion'=>$astra['contentVersion']];
request('admin-avatar-save',$editAstra);
$me=request('account-me',[])['user'];
check($me['avatarKey']==='astra'&&$me['profileImageUrl']===$uploaded['path']&&in_array('astra',$me['unlockedAvatarKeys'],true),'motif replacement retains current account selection and earned entitlement');
$newAstra=array_values(array_filter(request('admin-avatars')['avatars'],fn($a)=>$a['avatar_key']==='astra'))[0];
check($newAstra['label']==='Audit Astra'&&$newAstra['unlock_rule']==='hero_first_try','editing name and motif cannot change reward rule');
request('admin-avatar-save',['key'=>'astra','label'=>'No','image'=>$uploaded['path'],'unlockRule'=>'','contentVersion'=>$newAstra['contentVersion']],422);
check(!in_array($uploaded['path'],array_column(request('admin-media-list')['media'],'path'),true),'profile motifs are listed in the profile tab rather than duplicate general media entries');
request('admin-media-delete',['path'=>$uploaded['path']],404);replace_media(['path'=>$uploaded['path'],'version'=>'unused'],$png,422);
check(is_file(QUIZ_HERO_PUBLIC_ROOT.'/'.$uploaded['path']),'generic media actions cannot delete or bypass profile motif editing');
execute_sql_file(__DIR__.'/../database/migrations/017_avatar_catalog.sql');
check($pdo->query("SELECT label FROM quiz_avatars WHERE avatar_key='astra'")->fetchColumn()==='Audit Astra','replaying seed migration does not overwrite admin edits');
